<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-bg-1 {"backgroundType":"image","imagePc":"","imageSp":"","isFullWidth":true,"maxWidth":1040,"minHeightPc":"min-h-pc-150px","minHeightTb":"min-h-tb-160px","minHeightSp":"min-h-sp-160px","innerPaddingTopPc":80,"innerPaddingBottomPc":80,"innerPaddingLeftPc":40,"innerPaddingRightPc":40,"innerPaddingTopTb":64,"innerPaddingBottomTb":64,"innerPaddingLeftTb":32,"innerPaddingRightTb":32,"innerPaddingTopSp":48,"innerPaddingBottomSp":48,"innerPaddingLeftSp":20,"innerPaddingRightSp":20,"filterTypePc":"solid","filterColorPc":"#fdeff4","opacityPc":1,"filterTypeTb":"solid","filterColorTb":"#fdeff4","opacityTb":1,"filterTypeSp":"solid","filterColorSp":"#fdeff4","opacitySp":1} -->
<div class="wp-block-wdl-lw-bg-1 lw-bg-1 min-h-pc-150px min-h-tb-160px min-h-sp-160px bg_all" style="--lw-bg-color-filter-pc:#fdeff4;--lw-bg-opacity-pc:1;--lw-bg-color-filter-tb:#fdeff4;--lw-bg-opacity-tb:1;--lw-bg-color-filter-sp:#fdeff4;--lw-bg-opacity-sp:1;--lw-bg-position-pc:50% 50%;--lw-bg-position-sp:50% 50%;--lw-bg-wrap-centering-pc:center;--lw-bg-wrap-align-pc:center;--lw-bg-wrap-centering-tb:center;--lw-bg-wrap-align-tb:center;--lw-bg-wrap-centering-sp:center;--lw-bg-wrap-align-sp:center"><div class="lw-bg-1-wrap" style="--lw-bg-padding-top-pc:80px;--lw-bg-padding-bottom-pc:80px;--lw-bg-padding-left-pc:40px;--lw-bg-padding-right-pc:40px;--lw-bg-padding-top-tb:64px;--lw-bg-padding-bottom-tb:64px;--lw-bg-padding-left-tb:32px;--lw-bg-padding-right-tb:32px;--lw-bg-padding-top-sp:48px;--lw-bg-padding-bottom-sp:48px;--lw-bg-padding-left-sp:20px;--lw-bg-padding-right-sp:20px;--lw-bg-max-width:1040px"><!-- wp:wdl/lw-content-1 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/cs_me.webp","imageAlt":"運営者の写真","imagePosition":"left","linkText":""} -->
<div class="wp-block-wdl-lw-content-1 lw-content-1 left"><div class="lw-content-1__inner"><div class="lw-content-1__image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/cs_me.webp" alt="運営者の写真"/></div><div class="lw-content-1__text"><h3 class="lw_title" data-lw_font_set="">書いている人</h3><p class="lw_p" style="white-space:pre-wrap" data-lw_font_set="">はじめまして。ぷちラボを書いている〇〇です。

もともとは肌が弱く、合わないものを買っては捨てる、を何年もくり返していました。「誰かが実際に使った話」がいちばん知りたかったのに、検索して出てくるのは同じような紹介文ばかりで、結局どれも試すしかありませんでした。

だからこのサイトでは、<b>自分で買って、使ってから</b>書いています。合わなかったものは合わなかったと書きます。広告は入っていますが、それで順位を変えることはしません。

〇〇 〇〇（2019年〜）</p><a href="" class="lw-content-1__text_br_button" style="background-color:var(--color-accent);color:#fff" data-lw_font_set=""></a></div></div></div>
